# Count numbers m <= 100 such that m % 3 == 0 or m % 3 == 2, excluding m=2 and m=3.
count = 0
for m in range(1, 101):
    if (m % 3 == 0 or m % 3 == 2):
        if m >= 5:
            count += 1

print(f"The number of valid integers m is: {count}")

# We need to count positive integers m <= 100 such that m satisfies:
# 1. m % 3 == 0 AND m != 3
# 2. m % 3 == 2 AND m != 2

count = 0
for m in range(1, 101):
    is_valid = False
    if m % 3 == 0 and m != 3:
        is_valid = True
    elif m % 3 == 2 and m != 2:
        is_valid = True

    if is_valid:
        count += 1

print(count)
